"""Writes bench/RESULT_cost_curve.md from bench/out/cost_result.json (bench/PLAN_cost_curve.md); prose is added by
hand afterwards.  Usage  py -m bench.result_cost
"""
import json, os
HERE = os.path.dirname(os.path.abspath(__file__))
PRED = {1: .8, 2: 1.4, 4: 2.2, 8: 3.3, 16: 4.2}


def main():
    R = json.load(open(os.path.join(HERE, 'out', 'cost_result.json'), encoding='utf-8'))
    k = R['kev_fit']; L = []
    L += ['# The cost curve on an idle CPU: result', '',
          'GENERATED by `py -m bench.result_cost` from `bench/out/cost_result.json`; the prose is added by hand afterwards.',
          'Plan and hashes: `bench/PLAN_cost_curve.md`, `bench/PLAN_cost_curve.sha256`.', '',
          f"**Calls.** Kev: {R['calls_kev']} requests (one per passage, all its questions). Instruct model: "
          f"{R['questions_qwen']} requests (one per passage and question). 60 passages of 1,300-1,500 characters, each "
          'seen once per model.', '',
          '## Fit and medians',
          f"- Kev-4B: {k['s_per_passage']} s per passage + {k['s_per_question']} s per question (least squares over calls).",
          f"- Qwen3.5-4B instruct: {R['qwen_s_per_question_median']} s per question (median); first question of a passage "
          f"{R['qwen_first_question_median']} s, later ones {R['qwen_later_questions_median']} s (later/first "
          f"{R['qwen_later_over_first']}).",
          f"- Break-even: {R['break_even_questions']} questions per passage; ceiling ratio (instruct per question / Kev per "
          f"question): {R['ceiling_ratio']}x.", '',
          '## Per level', '| Questions per passage | Kev s per call (median) | Kev s per question | Instruct s per question | Instruct / Kev | Predicted |',
          '|---|---|---|---|---|---|']
    for q, v in sorted(R['levels'].items(), key=lambda kv: int(kv[0])):
        L.append(f"| {q} | {v['kev_s_per_call_median']} | {v['kev_s_per_question']} | {v['qwen_s_per_question']} | "
                 f"{v['qwen_over_kev']}x | {PRED[int(q)]}x |")
    L += ['', '## Predictions (from the plan)',
          '- Kev 5.5-7.5 s per passage and 0.8-1.2 s per question; instruct 5.5-6.5 s per question; later/first at least .85.', '']
    with open(os.path.join(HERE, 'RESULT_cost_curve.md'), 'w', encoding='utf-8') as f: f.write('\n'.join(L))
    print(os.path.join(HERE, 'RESULT_cost_curve.md'))


if __name__ == '__main__':
    main()
